package operator

import (
	"context"

	"github.com/jackc/pgx/v5/pgtype"
	"github.com/jackc/pgx/v5/pgxpool"

	"github.com/garamsh/garam/internal/errorx"
	"github.com/garamsh/garam/internal/grn"
	"github.com/garamsh/garam/internal/operator/db"
	"github.com/garamsh/garam/internal/pgxerr"
	"github.com/garamsh/garam/internal/pgxtype"
)

// PostgresStore implements Store against PostgreSQL. The queries are
// generated by sqlc from queries.sql.
type PostgresStore struct {
	pool *pgxpool.Pool
	q    *db.Queries
}

// Compile-time check that PostgresStore satisfies Store.
var _ Store = (*PostgresStore)(nil)

// NewPostgresStore constructs a Postgres-backed Store.
func NewPostgresStore(pool *pgxpool.Pool) *PostgresStore {
	return &PostgresStore{pool: pool, q: db.New(pool)}
}

// Register persists the record and reads the stored operator back in
// the same transaction: whether garam already issued a certificate for
// the GRN is in a table this write does not touch, so assuming none
// here would be wrong for a GRN `garam issue-certificate` minted for.
func (s *PostgresStore) Register(ctx context.Context, o *Operator) (*Operator, error) {
	tx, err := s.pool.Begin(ctx)
	if err != nil {
		return nil, errorx.Wrap(err, "begin", errorx.KindUnavailable)
	}
	defer func() { _ = tx.Rollback(ctx) }()

	q := s.q.WithTx(tx)
	if err := q.CreateOperator(ctx, db.CreateOperatorParams{
		Grn:          o.grn.String(),
		OrgGrn:       o.orgGRN.String(),
		RegisteredBy: o.registeredBy.String(),
		CreatedAt:    pgxtype.Timestamptz(o.createdAt),
		Name:         o.Name,
		Description:  o.Description,
	}); err != nil {
		return nil, pgxerr.Classify(err, "register operator", nil, ErrOperatorAlreadyRegistered)
	}
	row, err := q.GetOperator(ctx, o.grn.String())
	if err != nil {
		return nil, pgxerr.Classify(err, "read registered operator", nil, nil)
	}
	registered, err := rowToOperator(row.Operator, row.CertificateIssuedAt)
	if err != nil {
		return nil, err
	}
	if err := tx.Commit(ctx); err != nil {
		return nil, errorx.Wrap(err, "commit")
	}
	return registered, nil
}

// UpdateDetails writes the patch and reads the operator back in one
// transaction, so the answer is the row this write left rather than
// one a concurrent write replaced in between.
func (s *PostgresStore) UpdateDetails(ctx context.Context, g grn.GRN, patch DetailsPatch) (*Operator, error) {
	tx, err := s.pool.Begin(ctx)
	if err != nil {
		return nil, errorx.Wrap(err, "begin", errorx.KindUnavailable)
	}
	defer func() { _ = tx.Rollback(ctx) }()

	q := s.q.WithTx(tx)
	n, err := q.UpdateOperatorDetails(ctx, db.UpdateOperatorDetailsParams{
		Grn:         g.String(),
		Name:        optionalText(patch.name),
		Description: optionalText(patch.description),
	})
	if err != nil {
		return nil, pgxerr.Classify(err, "update operator details", nil, nil)
	}
	if n == 0 {
		return nil, ErrOperatorNotFound
	}
	row, err := q.GetOperator(ctx, g.String())
	if err != nil {
		return nil, pgxerr.Classify(err, "read updated operator", ErrOperatorNotFound, nil)
	}
	updated, err := rowToOperator(row.Operator, row.CertificateIssuedAt)
	if err != nil {
		return nil, err
	}
	if err := tx.Commit(ctx); err != nil {
		return nil, errorx.Wrap(err, "commit")
	}
	return updated, nil
}

// SetControlEndpoint writes the endpoint and reads the operator back in
// one transaction, as UpdateDetails does.
func (s *PostgresStore) SetControlEndpoint(ctx context.Context, g grn.GRN, endpoint *ControlEndpoint) (*Operator, error) {
	tx, err := s.pool.Begin(ctx)
	if err != nil {
		return nil, errorx.Wrap(err, "begin", errorx.KindUnavailable)
	}
	defer func() { _ = tx.Rollback(ctx) }()

	q := s.q.WithTx(tx)
	n, err := q.SetOperatorControlEndpoint(ctx, db.SetOperatorControlEndpointParams{
		Grn:             g.String(),
		ControlEndpoint: optionalText((*string)(endpoint)),
	})
	if err != nil {
		return nil, pgxerr.Classify(err, "set operator control endpoint", nil, nil)
	}
	if n == 0 {
		return nil, ErrOperatorNotFound
	}
	row, err := q.GetOperator(ctx, g.String())
	if err != nil {
		return nil, pgxerr.Classify(err, "read operator", ErrOperatorNotFound, nil)
	}
	updated, err := rowToOperator(row.Operator, row.CertificateIssuedAt)
	if err != nil {
		return nil, err
	}
	if err := tx.Commit(ctx); err != nil {
		return nil, errorx.Wrap(err, "commit")
	}
	return updated, nil
}

// Delete removes the record and the record of the certificate garam
// last issued the operator, in one transaction.
//
// The transaction holds the registration first, as every writer of
// the operator's keys and tokens does, and then deletes
// every token the operator holds or is the audience of in token_hash
// order, the order every statement waiting on several tokens takes
// them in. The cascades would take them in their own orders, and the
// audience's reaches tokens of other operators whose registrations it
// does not hold (#1424).
//
// The statements are one transaction, so a failure part way deletes
// nothing. Their order is the one above: the registration, then the
// tokens, then the rest.
func (s *PostgresStore) Delete(ctx context.Context, g grn.GRN) error {
	tx, err := s.pool.Begin(ctx)
	if err != nil {
		return errorx.Wrap(err, "begin", errorx.KindUnavailable)
	}
	defer func() { _ = tx.Rollback(ctx) }()

	q := s.q.WithTx(tx)
	if _, err := q.LockOperatorRegistration(ctx, g.String()); err != nil {
		return pgxerr.Classify(err, "hold operator", ErrOperatorNotFound, nil)
	}
	if err := q.DeleteOperatorTokens(ctx, g.String()); err != nil {
		return pgxerr.Classify(err, "delete operator tokens", nil, nil)
	}
	if err := q.DeleteOperatorCertificate(ctx, g.String()); err != nil {
		return pgxerr.Classify(err, "delete operator certificate", nil, nil)
	}
	// The registration is held FOR UPDATE, so the row is there to
	// delete; an absent one was refused by the hold.
	if _, err := q.DeleteOperator(ctx, g.String()); err != nil {
		return pgxerr.Classify(err, "delete operator", nil, nil)
	}
	if err := tx.Commit(ctx); err != nil {
		return errorx.Wrap(err, "commit")
	}
	return nil
}

// Get returns the organization's record of the operator.
func (s *PostgresStore) Get(ctx context.Context, g grn.GRN) (*Operator, error) {
	row, err := s.q.GetOperator(ctx, g.String())
	if err != nil {
		return nil, pgxerr.Classify(err, "get operator", ErrOperatorNotFound, nil)
	}
	return rowToOperator(row.Operator, row.CertificateIssuedAt)
}

// ListByOrg returns the organization's operators.
func (s *PostgresStore) ListByOrg(ctx context.Context, orgGRN grn.GRN) ([]*Operator, error) {
	rows, err := s.q.ListOperatorsByOrg(ctx, orgGRN.String())
	if err != nil {
		return nil, pgxerr.Classify(err, "list operators", nil, nil)
	}
	operators := make([]*Operator, 0, len(rows))
	for _, row := range rows {
		o, err := rowToOperator(row.Operator, row.CertificateIssuedAt)
		if err != nil {
			return nil, err
		}
		operators = append(operators, o)
	}
	return operators, nil
}

// CountByOrg counts the organization's registered operators, which
// deleting the organization removes with it. A certificate one of them
// already holds is not counted: that row carries no foreign key and
// survives both the registration and the organization (ADR-0045
// errata).
func (s *PostgresStore) CountByOrg(ctx context.Context, orgGRN grn.GRN) (int, error) {
	n, err := s.q.CountOperatorsByOrg(ctx, orgGRN.String())
	if err != nil {
		return 0, pgxerr.Classify(err, "count operators by org", nil, nil)
	}
	return int(n), nil
}

// rowToOperator converts a sqlc row and the certificate date joined
// beside it into the domain aggregate. A stored GRN that no longer
// parses is data corruption, hence internal.
func rowToOperator(row db.Operator, certificateIssuedAt pgtype.Timestamptz) (*Operator, error) {
	g, err := grn.Parse(row.Grn)
	if err != nil {
		return nil, errorx.Wrap(err, "grn", errorx.KindInternal)
	}
	orgGRN, err := grn.Parse(row.OrgGrn)
	if err != nil {
		return nil, errorx.Wrap(err, "org grn", errorx.KindInternal)
	}
	if err := validateOwnership(g, orgGRN); err != nil {
		return nil, errorx.Wrap(err, "stored operator", errorx.KindInternal)
	}
	registeredBy, err := grn.Parse(row.RegisteredBy)
	if err != nil {
		return nil, errorx.Wrap(err, "registered by", errorx.KindInternal)
	}
	var endpoint *ControlEndpoint
	if row.ControlEndpoint.Valid {
		e, err := ParseControlEndpoint(row.ControlEndpoint.String)
		if err != nil {
			return nil, errorx.Wrap(err, "control endpoint", errorx.KindInternal)
		}
		endpoint = &e
	}
	return &Operator{
		grn:             g,
		orgGRN:          orgGRN,
		registeredBy:    registeredBy,
		createdAt:       row.CreatedAt.Time,
		Name:            row.Name,
		Description:     row.Description,
		ControlEndpoint: endpoint,
		// An absent certificate leaves the zero time, which is what
		// CertificateIssuedAt answers as "garam has issued none".
		certificateIssuedAt: certificateIssuedAt.Time,
	}, nil
}

// optionalText converts an absent string to SQL NULL, which the update
// reads as "leave the column as it stands".
func optionalText(s *string) pgtype.Text {
	if s == nil {
		return pgtype.Text{}
	}
	return pgtype.Text{String: *s, Valid: true}
}
